use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.root < 0 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur]
            if x == k {
                return false
            }
            let go_left = x < k
            let next = if go_left { self.lefts[cur] } else { self.rights[cur] }
            if next < 0 {
                let idx = self.keys.len() as int
                self.keys.push(x)
                self.lefts.push(-1)
                self.rights.push(-1)
                if go_left {
                    self.lefts[cur] = idx
                } else {
                    self.rights[cur] = idx
                }
                return true
            }
            cur = next
        }
        false
    }

    fn set_child(self, parent: int, was_left: bool, child: int) {
        if parent < 0 {
            self.root = child
        } else if was_left {
            self.lefts[parent] = child
        } else {
            self.rights[parent] = child
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut was_left = false
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                was_left = true
                cur = self.lefts[cur]
            } else {
                was_left = false
                cur = self.rights[cur]
            }
        }
        if cur < 0 {
            return false
        }
        let l = self.lefts[cur]
        let r = self.rights[cur]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            while self.lefts[s] >= 0 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[cur] = self.keys[s]
            let sr = self.rights[s]
            if sp == cur {
                self.rights[cur] = sr
            } else {
                self.lefts[sp] = sr
            }
        } else if l >= 0 {
            self.set_child(parent, was_left, l)
        } else {
            self.set_child(parent, was_left, r)
        }
        true
    }

    fn height_of(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.height_of(self.lefts[n])
        let b = self.height_of(self.rights[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn collect(self, n: int, out: Vec<int>) {
        if n < 0 {
            return
        }
        self.collect(self.lefts[n], out)
        out.push(self.keys[n])
        self.collect(self.rights[n], out)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<int> = []
            t.collect(t.root, out)
            if out.len() == 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = out.map(|v| "${v}").collect()
                println(strs.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lefts[c] >= 0 { c = t.lefts[c] }
                } else {
                    while t.rights[c] >= 0 { c = t.rights[c] }
                }
                println("${t.keys[c]}")
            }
        }
    }
}

